CREATE TABLE T_P456_RAW(id INT, age INT);
CREATE VIEW V_P456_RAW AS SELECT id, age, id + age AS data FROM T_P456_RAW;
SELECT COUNT(*) FROM V_P456_RAW;
SELECT COUNT(id) FROM V_P456_RAW;
SELECT COUNT(data) FROM V_P456_RAW;
SELECT SUM(age) FROM V_P456_RAW;
SELECT COUNT(*) FROM V_P456_RAW WHERE id IS NULL;
SELECT COUNT(*) FROM V_P456_RAW WHERE id IS NOT NULL;
CREATE VIEW V_P456_FULL AS SELECT id, age FROM T_P456_RAW;
UPDATE V_P456_FULL SET age = 46 WHERE id = 21000;
DELETE FROM V_P456_FULL WHERE id = 21000;
CREATE VIEW V_P456_PART AS SELECT id, age FROM T_P456_RAW;
UPDATE V_P456_PART SET age = 60 WHERE id = 22000;
DELETE FROM V_P456_PART WHERE id = 22000;
CREATE VIEW V_P456_EXPR AS SELECT id, age, id + age AS data FROM T_P456_RAW;
SELECT COUNT(*) FROM V_P456_EXPR WHERE data IS NOT NULL;
CREATE TABLE T_P456_EXTRA(id INT, score INT);
CREATE VIEW V_P456_JOIN AS SELECT t.id, t.age, e.score FROM T_P456_RAW t, T_P456_EXTRA e WHERE (t.id IS NOT NULL AND t.id = e.id) OR (t.id IS NULL AND e.id IS NULL);
SELECT COUNT(*) FROM V_P456_JOIN;
UPDATE V_P456_JOIN SET age = age + 1 WHERE id = 500;
UPDATE T_P456_RAW SET age = age - 1 WHERE id = 500;
CREATE VIEW V_P456_AGG AS SELECT COUNT(*) AS cnt, SUM(age) AS total FROM T_P456_RAW;
SELECT cnt, total FROM V_P456_AGG;
SELECT COUNT(*) FROM T_P456_RAW;
